import runpy
from pathlib import Path

g = runpy.run_path(str(Path(__file__).with_name('build_reading_guides.py')))
out = g['OUT']
for name in ['attention', 'compression']:
    (out / f'{name}-advanced.html').write_text((out / f'{name}-reading.html').read_text(encoding='utf-8'), encoding='utf-8')

flow, quiz, section = g['flow'], g['quiz'], g['section']
g['make'].__globals__['CSS'] += '''
.story{font-size:clamp(21px,3vw,29px);line-height:2.2;padding:12px 0}.word{display:inline-block;padding:2px 9px;margin:4px;border-radius:6px;background:#e8ece7}.word.hot{background:#087c7c;color:white}.word.target{background:#f6dcb2}.storyline{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:14px 0}.stage{min-height:110px}.readfirst{font-size:20px;font-weight:600}details{background:transparent}.visual p{max-width:65ch}.barrow{grid-template-columns:80px 1fr 80px}.hidden{display:none!important}
'''

def build(name,title,subtitle,source,items,js,other):
    sections=[(i,t,section(i,t,'概念入门 · '+r,b)) for i,t,r,b in items]
    g['make'](name,title,subtitle,source,sections,js,other)
    p=out/name
    text=p.read_text(encoding='utf-8').replace('论文精读 / READING LAB','从一个例子开始').replace('先看直觉，再动手，最后回到原文。','先顺着故事看。想研究数学时，再展开公式。').replace('每节约 5–10 分钟','每节约 2–4 分钟').replace('本页提供关键概念的中文释义和独立教学示例，并非全文逐句翻译。所有可操作的示例均为简化模型，未调用真实大模型。标为“论文数据”的数值来自指定原文位置。','先把一个问题想明白，再认识它的名称。互动里的词、分数和回答都是人为教学示例，不是真实模型的输出。')
    p.write_text(text,encoding='utf-8')

A=[
('b1','01 · 同一个词，为什么有不同意思？','对应原文 §3：上下文表示', '''<p class="readfirst">先别管论文。我们先试着读懂“苹果”这个词。</p><div class="visual"><div class="row"><button id="fruit" aria-pressed="true">句子一</button><button id="phone" aria-pressed="false">句子二</button></div><div id="apple" class="story"></div><p id="appleExplain" class="stage" aria-live="polite"></p></div><p>你判断词义时，会看周围的词。模型也需要一种办法：让一个位置参考其他位置的信息，得到更符合当前句子的表示。</p><p><b>Attention，注意力，就是完成这种信息参考与汇集的一种计算方法。</b>它在模型内部操作数字向量；这里先用词语帮助你理解。</p>'''),
('b2','02 · 读到“她”，该回头看谁？','对应原文 §3.2：注意力', '''<div class="visual"><div class="story">小明把球递给<span class="word" id="red">小红</span>，<span class="word target">她</span>接住了。</div><p>现在要理解黄色的“她”。先想一想：你会重点参考哪里？</p><button id="look">看一次信息如何流动</button><div id="lookResult" class="stage" aria-live="polite">点击后再看解释。</div></div><p>理解“她”时，“小红”提供了有用线索；“递给”“接住”也帮助理解事件。注意力的思路是：给各处信息分配不同的参考程度，再把它们汇集到当前位置。</p><p>这不是说模型真的在心里问“她是谁”，也不是只挑一个词。它把多个位置的数字表示，按不同权重组合起来。</p>'''),
('b3','03 · “更关注”到底做了什么？','对应原文 §3.2.1：加权汇集', '''<p>先把权重当作“参考程度”：参考多的地方，对这次汇集影响更大。下面用人为分配的 10 份参考量演示。</p><div class="visual"><label>给“小红”的参考量：<input id="share" type="range" min="0" max="10" value="6"> <output id="shareOut"></output></label><div id="shares"></div><p id="shareExplain" aria-live="polite"></p><p class="small">为便于比较，其余参考量按固定比例分配。真实网络通过训练得到向量，再计算权重；不是人手拖这个滑块。</p></div>'''+flow('各处的信息','按参考程度组合','得到当前“她”的新表示')+'''<p><b>注意力产生的是一份新的数字表示。</b>后面的网络再用它来理解、翻译或预测。它不会仅靠这个步骤直接输出“小红”两个字。</p>'''+quiz('如果两个位置都有用，是否只能二选一？','不用。可以同时参考两个位置，只是参考程度不同。这就是“加权组合”的意思。')),
('b4','04 · Q、K、V：给刚才的过程起名字','对应原文 §3.2：Query / Key / Value', '''<p>这三个字母一直在描述刚才同一件事。按“下一步”逐个看。</p><div class="visual"><div class="row"><button id="qprev">上一步</button><button id="qnext">下一步</button><output id="qcount"></output></div><div id="qstory" class="stage" aria-live="polite"></div></div><table><tr><th>名称</th><th>先这样理解</th></tr><tr><td>Q：查询线索</td><td>当前位置用什么特征去匹配别处？</td></tr><tr><td>K：匹配线索</td><td>别的位置提供什么特征供比较？</td></tr><tr><td>V：待汇集的信息</td><td>匹配程度确定后，从那里取用什么内容？</td></tr></table><p>同一个位置可以同时产生 Q、K、V。它既能参考别人，也能被别人参考。它们都是模型从输入向量变换出来的数字，并非人工写好的问题和答案。</p>'''+quiz('为什么匹配线索 K 和实际汇集的信息 V 要分开？','用于判断“这条信息和我有没有关系”的特征，与最终要取用的内容可以不同。分开变换，给模型更多学习空间。比如你按书名找书，但最终读取的是书的内容；这只是类比。')+'''<details><summary>现在想看公式，再展开</summary><div class="formula">Attention(Q,K,V) = softmax(QKᵀ / √d_k) V</div><ol><li>QKᵀ：计算各位置之间的匹配分数。</li><li>除以 √d_k：控制分数幅度，帮助计算更稳定。</li><li>softmax：把分数变成总和为 1 的参考权重。</li><li>乘 V：按权重汇集信息。</li></ol><p>先记“匹配 → 分配参考量 → 汇集信息”，不用现在推矩阵。</p></details>'''),
('b5','05 · 多头：同时做几次不同的参考','对应原文 §3.2.2：多头注意力', '''<p>一次参考可能不够。模型可以用不同的变换做几次注意力计算，然后把结果合并，这叫<b>多头注意力</b>。</p>'''+flow('同一句话','不同的头分别计算','合并各头结果','形成新表示')+'''<div class="visual"><label>看哪种线索：<select id="lens"><option value="0">“她”可能指谁</option><option value="1">发生了什么动作</option><option value="2">动作涉及什么物品</option></select></label><div id="lensSentence" class="story"></div><p id="lensExplain" aria-live="polite"></p></div><p class="small">这里是人为设计的三个阅读角度，只帮助理解“不同投影”。真实注意力头并没有被固定命名为“人物头”“动作头”，也不保证分工这样清晰。</p>'''+quiz('“多头”意味着启动了多个大模型吗？','这里指同一层内部的多组注意力计算，不是启动多个完整模型或多个 Agent。')),
('b6','06 · 为什么生成时要遮住后面的词？','对应原文 §3.1、§3.2.3：因果遮罩', '''<p>想象一个补句游戏：你每次只看到已经写出来的内容，猜下一个词。如果提前把答案给你看，练习就失去了意义。</p><div class="visual"><p>本轮输入前缀：</p><div id="prefix" class="story"></div><p id="target" aria-live="polite"></p><button id="writeNext">写出下一个词</button><button id="writeReset">从头开始</button><p class="small">示例按预先写好的“我 爱 你”逐步播放，不是真实预测。</p></div><p>训练时，完整目标句已经知道；系统把输入右移一格，并限制每个位置只能读到相应前缀。这个限制叫<b>因果遮罩</b>。推理时，后面的输出还没生成，通常要一步步写。</p><p><b>能并行训练，不等于回答时能提前知道整句话。</b>编码器阅读完整源句时，则可以参考整句中允许访问的位置。</p>'''),
('b7','07 · Transformer 是把这些步骤接起来','对应原文 Figure 1：编码器与解码器', '''<p>用英译中走一遍。先只看信息从哪里到哪里。</p><div class="visual"><div class="row"><button id="tprev">上一步</button><button id="tnext">下一步</button><output id="tcount"></output></div><div id="translation" class="stage" aria-live="polite"></div></div>'''+flow('读源句的编码器','源句的数字表示','结合已写前缀的解码器','下一个词的概率')+'''<p>原论文把注意力、前馈网络等步骤堆成多层。前馈网络可以先理解为“在每个位置进一步处理刚才汇集到的信息”。残差帮助保留并传递原有表示，归一化帮助控制数值。</p><details><summary>“自注意力”和“交叉注意力”的区别</summary><p>同一句内部互相参考，叫自注意力。解码器写译文时参考编码器提供的源句表示，叫交叉注意力。前者的 Q/K/V 来自同一条序列，后者的 Q 与 K/V 来自不同序列。</p></details><details><summary>论文标题真的意味着“只需要注意力”？</summary><p>标题强调使用注意力替代当时常用的循环或卷积主干。Transformer 仍包含嵌入、位置信息、前馈网络、残差、归一化等部件。这里讲的是 2017 年原始编码器—解码器，不等同于所有现代聊天模型的结构。</p></details>'''),
('b8','08 · 先确认这三件事就够了','学习检查与原文入口', '''<p>不用背公式。试着用自己的话解释下面三题，再展开答案。</p>'''+quiz('1. 注意力在做什么？','为理解或处理当前位置，计算它与其他位置的匹配程度，再按权重汇集各处信息，得到新的表示。')+quiz('2. Q、K、V 在刚才故事里分别做什么？','Q 提供当前查询的匹配线索，K 提供各处被比较的线索，V 提供最后要汇集的信息。它们实际上是数字向量。')+quiz('3. 为什么不同的头可能看到不同关系？','它们有不同的学习参数，会把输入变换到不同的表示空间，再分别计算和合并。不能保证每个头都有一个人能清晰命名的专职。')+'''<p>能解释这三题后，再回看第 4 节展开公式，把符号逐个对应上。</p><p><a href="attention-advanced.html">准备好后，进入原来的矩阵与论文精读版 ↗</a></p><p class="foot">原文：<a href="https://arxiv.org/html/1706.03762v7">Attention Is All You Need</a>，重点对照 §3.2 与 Figure 1–2。本页故事、权重、演示为原创教学示意，未展示真实模型的注意力或解释其因果机制。</p>''')]

ajs='''
const $=id=>document.getElementById(id);
function apple(phone){$('apple').innerHTML=phone?'这部<span class="word target">苹果</span>手机的<span class="word hot">电池</span>很耐用。':'这个<span class="word target">苹果</span>吃起来很<span class="word hot">甜</span>。';$('appleExplain').textContent=phone?'“手机”“电池”让你把苹果理解为产品品牌。':'“吃起来”“甜”让你把苹果理解为水果。';$('fruit').setAttribute('aria-pressed',!phone);$('phone').setAttribute('aria-pressed',phone)}$('fruit').onclick=()=>apple(false);$('phone').onclick=()=>apple(true);apple(false);
$('look').onclick=()=>{$('red').classList.add('hot');$('lookResult').innerHTML='<div class="storyline"><span class="word hot">小红的信息</span><span>→</span><span class="word target">用于更新“她”的表示</span></div><p>这次重点参考“小红”，帮助理解“她”在这句话中的含义。</p>'};
function shares(){const n=+$('share').value,rest=10-n;const arr=[['小红',n],['递给',rest*.5],['接住',rest*.3],['其他',rest*.2]];$('shareOut').textContent=n+' / 10 份';$('shares').innerHTML=arr.map(([s,v])=>`<div class="barrow"><span>${s}</span><div class="track"><div class="fill" style="width:${v*10}%"></div></div><output>${v.toFixed(1)} 份</output></div>`).join('');$('shareExplain').textContent=n===0?'现在完全没有汇入“小红”的信息；这个操作只是演示信息配比，不生成新的理解结果。':'“小红”占 '+n+' 份参考量，其余位置合计 '+rest+' 份。总量始终是 10 份。'}$('share').oninput=shares;shares();
const qs=['<h3>① 先确定当前位置的线索 Q</h3><p>我们正在处理“她”。它的向量经过一个变换，得到本次用于寻找相关信息的线索。</p>','<h3>② 把 Q 与各处的 K 比较</h3><p>“小明”“递给”“小红”等位置各有匹配线索。比较后得到不同分数，再转成参考权重。</p>','<h3>③ 按权重汇集各处的 V</h3><p>每个位置还有待取用的信息 V。把它们按权重组合，就形成“她”的新表示。</p>'];let q=0;function qdraw(){$('qstory').innerHTML=qs[q];$('qcount').textContent=(q+1)+' / 3';$('qprev').disabled=q===0;$('qnext').disabled=q===2}$('qprev').onclick=()=>{q--;qdraw()};$('qnext').onclick=()=>{q++;qdraw()};qdraw();
function lens(){const k=+$('lens').value;const words=['小明','把','球','递给','小红','，她接住了。'];const wanted=[4,3,2][k];$('lensSentence').innerHTML=words.map((w,i)=>`<span class="word ${i===wanted?'hot':''}">${w}</span>`).join('');$('lensExplain').textContent=['人物线索：重点看看“小红”。','动作线索：重点看看“递给”。','物品线索：重点看看“球”。'][k]}$('lens').onchange=lens;lens();
let n=0;const words=['我','爱','你'];function write(){$('prefix').textContent='[起始符] '+words.slice(0,n).join(' ');$('target').textContent=n<3?'接下来要预测：'+words[n]+'（这里为教学揭示答案；模型输入不含这个答案）':'句子写完了，接下来可以生成结束符。';$('writeNext').disabled=n===3}$('writeNext').onclick=()=>{n++;write()};$('writeReset').onclick=()=>{n=0;write()};write();
const ts=['<h3>① 编码器阅读源句</h3><p>输入 I love you。各词通过注意力参考源句中的其他词，形成带上下文的数字表示。</p>','<h3>② 解码器先写第一个词</h3><p>根据源句表示和起始符，形成目标词的概率。我们假定示例选出“我”。</p>','<h3>③ 结合已经写出的内容继续写</h3><p>根据源句表示和“我”，继续形成概率，示例选出“爱”。下一轮再结合“我 爱”写“你”。</p>','<h3>④ 多层处理后得到每次预测</h3><p>内部反复参考信息、处理表示，最终输出下一 token 的概率。这套网络结构叫 Transformer。</p>'];let t=0;function trans(){$('translation').innerHTML=ts[t];$('tcount').textContent=(t+1)+' / 4';$('tprev').disabled=t===0;$('tnext').disabled=t===3}$('tprev').onclick=()=>{t--;trans()};$('tnext').onclick=()=>{t++;trans()};trans();
'''
build('attention-reading.html','Attention：读一个词时，该参考哪里？','沿着一句话走完注意力。先看懂过程，再认识 Q、K、V。','https://arxiv.org/html/1706.03762v7',A,ajs,'compression-reading.html')

C=[('e1','01 · 一长串数字，也能用一句话记住','规律与压缩的直觉','''<p>看这串数：</p><div class="visual"><div class="story">2、4、6、8、10、12、14、16</div><button id="rule">换一种记法</button><p id="ruleText" class="stage" aria-live="polite">先想想，你会怎么告诉一个没看过它的人？</p></div><p>规律让你少记一些具体内容。遇到例外，仍需额外保存例外。这个故事解释压缩的直觉，不是论文中的数值实验。</p>'''),('e2','02 · 越容易猜到，通常越省信息','预测与编码','''<p>假设你和朋友约定了一本共同的代码表，常见消息用短代码，少见消息用长代码。</p><div class="visual"><table><tr><th>消息</th><th>教学用代码</th></tr><tr><td>到家了（最常见）</td><td>0</td></tr><tr><td>晚点到</td><td>10</td></tr><tr><td>需要帮忙</td><td>11</td></tr></table><label>要发哪条消息？<select id="message"><option value="0">到家了</option><option value="10">晚点到</option><option value="11">需要帮忙</option></select></label><p id="messageOut" class="story" aria-live="polite"></p></div><p>这里每条消息都能完整恢复，短代码没有删掉消息的意思；朋友得知道同一张表。真正编码时，可以使用预测模型提供的概率来安排编码，而不用只靠这种手写小表。</p>'''),('e3','03 · 大模型和压缩有什么关系？','论文 §2 的核心联系','''<p>模型反复学习：看到前面的内容，接下来通常是什么？如果它把实际发生的内容预测得更合适，配合编码器，平均就能更省空间。</p>'''+flow('模型预测概率','编码器安排编码','传输较短的码','解码器 + 相同模型还原')+'''<p>这一步既需要预测模型，也需要编码与解码规则。单独让聊天模型“猜回原文”，不能保证一字不差。</p><details><summary>想知道数学关系，再展开</summary><p>理想码长约为 −log₂ p。p=1/2 时是 1 bit，p=1/8 时是 3 bit。意思是：实际发生的内容越出乎模型意料，需要的信息越多。多个符号通常一起编码，实际实现还有开销。</p></details>'''),('e4','04 · 好压缩不一定就是完整的智能','观点的适用边界','''<p>“A 重复一万次”很容易压缩，但完成它的小程序不一定能理解故事或解决新问题。智能讨论更关心学到的规律能否帮助处理没见过的情况。</p><p>论文题目《语言建模就是压缩》讨论明确的预测与编码联系。“压缩即智能”则是更宽的解释视角，不能直接当成“压缩率衡量一切能力”的证明。</p><div class="visual"><p><b>用到你正在学的 Agent：</b></p><p>把“必须用 CUDA 12.4”缩成“用较新的 CUDA”，虽然更短，却可能让任务失败。</p><p>所以任务摘要要保住关键约束，并能查回原始证据。</p></div>'''),('e5','05 · 先回答这两题','检查理解与进一步阅读',quiz('为什么双方要共享模型或代码规则？','接收方需要知道编码所依据的规则，才能把短代码还原成原来的信息。这些规则本身也有保存或传输成本。')+quiz('为什么说“会预测”有助于压缩？','预测器提供哪些内容更可能出现的概率，编码器利用这些概率安排更节省的表示。匹配实际数据的预测，能降低平均编码代价。')+'''<p><a href="compression-advanced.html">理解后再看：算术编码、实验数据和模型体积 ↗</a></p><p class="foot">原文：<a href="https://arxiv.org/html/2309.10668v2">Language Modeling Is Compression</a>。上面的序列、消息表是独立教学示例，不是论文实验。</p>''')]
cjs='''const $=id=>document.getElementById(id);$('rule').onclick=()=>{$('ruleText').innerHTML='<b>从 2 开始，每次加 2，共 8 个数。</b><br>对方按规则就能还原；不用逐个背。'};function msg(){const c=$('message').value;$('messageOut').textContent='发送 '+c+' → '+c.length+' 个二进制位；对方按表还原消息。'}$('message').onchange=msg;msg();'''
build('compression-reading.html','压缩：把规律记住，会发生什么？','从一串数字和三条消息，理解“预测为什么能帮助压缩”。','https://arxiv.org/html/2309.10668v2',C,cjs,'attention-reading.html')
print('Beginner guides updated; advanced guides retained.')
